private function createPromotion(
    string $name,
    ?string $description = null,
    ?string $code = null,
    array $channels = [],
    ?array $rules = null,
    ?array $actions = null,
    array $coupons = [],
    ?int $priority = null,
    ?int $usageLimit = null,
    bool $couponBased = false,
    bool $exclusive = false,
    bool $appliesToDiscounted = true,
    ?string $startsAt = null,
    ?string $endsAt = null,
): PromotionInterface {
    if (empty($channels) && $this->sharedStorage->has('channel')) {
        $channels = [$this->sharedStorage->get('channel')];
    }

    $code ??= StringInflector::nameToCode($name);

    /** @var PromotionInterface $promotion */
    $promotion = $this->promotionExampleFactory->create([
        'name' => $name,
        'description' => $description,
        'code' => $code,
        'channels' => $channels,
        'rules' => $rules,
        'actions' => $actions,
        'coupons' => $coupons,
        'priority' => $priority,
        'usage_limit' => $usageLimit,
        'coupon_based' => $couponBased,
        'exclusive' => $exclusive,
        'applies_to_discounted' => $appliesToDiscounted,
        'starts_at' => $startsAt,
        'ends_at' => $endsAt,
    ]);

    $this->promotionRepository->add($promotion);
    $this->sharedStorage->set('promotion', $promotion);

    return $promotion;
}

